const input=$input.first()?.json||{};
const text=String(input.text||input.messageText||input.question||'').normalize('NFKC').trim();
const clean=v=>String(v??'').normalize('NFKC').trim();
if(input.principalKey||input.storageUsername||input.telegramActorId||input.telegramUserId){
 const actor=clean(input.telegramActorId||input.telegramUserId);const storage=clean(input.storageUsername||input.userId||input.memoryUserId).toLowerCase();
 if(!/^\d+$/.test(actor)||Number(actor)<=0)throw new Error('task shadow numeric Telegram actor required');
 if(!/^tgactor_[a-f0-9]{64}$/.test(clean(input.principalKey)))throw new Error('task shadow principal invalid');
 if(!/^actor_[a-f0-9]{32}$/.test(storage))throw new Error('task shadow storage invalid');
 if(clean(input.telegramActorId)&&clean(input.telegramUserId)&&clean(input.telegramActorId)!==clean(input.telegramUserId))throw new Error('task shadow actor mismatch');
 if(clean(input.userId)&&clean(input.userId)!==storage)throw new Error('task shadow userId mismatch');
}
const explicit=/(?:напомни|напомнить|поставь\s+(?:задачу|напоминание)|создай\s+(?:задачу|напоминание)|запланируй|добавь\s+(?:задачу|напоминание)|\bremind me\b|\bcreate (?:a )?task\b)/iu;
const list=/^(?:покажи|покажи мне|какие|список)\s+(?:мои\s+)?(?:задачи|напоминания)(?:\s|$)/iu;
const imperative=/^(?:купить|позвонить|сделать|отправить|проверить|забрать|записаться|оплатить|выключить|подготовить)(?:\s|$)[\s\S]{0,160}(?:сегодня|завтра|послезавтра|через\s+\d+|в\s+\d{1,2}(?::\d{2})?)/iu;
const cadence=/^(?:(?:добавь|запланируй|создай)\s+)?(?:ежедневно|еженедельно|ежемесячно|кажд(?:ый|ую|ое)\s+(?:день|утро|вечер|неделю|месяц|понедельник|вторник|среду|четверг|пятницу|субботу|воскресенье))\s+(?:зарядк[ауи]?|тренировк[ауи]?|пробежк[ауи]?|медитаци[яюи]|чтени[ея]|прогулк[ауи]?|уборк[ауи]?|[\p{L}-]{3,}(?:ть|ти|чь))/iu;
const conversational=/^(?:как|почему|что\s+ты\s+думаешь|расскажи|объясни|помоги\s+понять|можешь\s+ли\s+обсудить)(?:\s|,|$)/iu;
const ambiguous=/(?:надо|нужно|хочу|не забыть|когда-нибудь|в ближайшее время)|^(?:готово|выполнено|сделал(?:а)?)$/iu;
let route='not_a_task_command',reason='no_task_signal';
if(input.isEdited||input.isForwarded){route='not_a_task_command';reason='untrusted_update';}
else if(input.inputType==='callback'&&input.callbackScope==='chelsea_task_v1'){route='task_answer';reason='trusted_task_callback';}
else if(!text){route='not_a_task_command';reason='empty';}
else if(list.test(text)||explicit.test(text)||imperative.test(text)||cadence.test(text)){route='task_command';reason='explicit_task_intent';}
else if(conversational.test(text)){route='not_a_task_command';reason='conversation';}
else if(ambiguous.test(text)){route='ambiguous';reason='needs_confirmation';}
return [{json:{...input,shadowDecision:{route,reason},shadowOnly:true,identityFieldContract:'telegramActorId_numeric__storageUsername_actor_namespace'}}];
